import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DiAOIirN.js";var i=JSON.parse(`{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1788290860000}`),a={name:`guide/getting-started.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><ul><li>Node.js 22 or newer</li><li>An SMTP account you may send from — a submission server on port 587 or 465, with a username and password. Providers with two-factor authentication generally need an app-specific password rather than the account password.</li></ul><h2 id="try-it-without-sending-anything" tabindex="-1">Try it without sending anything <a class="header-anchor" href="#try-it-without-sending-anything" aria-label="Permalink to “Try it without sending anything”">​</a></h2><p>The server starts perfectly well with sending switched off, which is the default. That state is useful on its own: you can compose messages, see exactly what would go out, and check who the server would be allowed to write to — without any possibility of a message escaping while you are still working out the configuration.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">SMTP_HOST</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">smtp.example.net</span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;"> \\</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">SMTP_USER=person@example.net </span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">\\</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">SMTP_PASSWORD=app-specific-password </span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">\\</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">SMTP_FROM=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&#39;Your Name &lt;person@example.net&gt;&#39;</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">npx </span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">-y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> @ni-c/smtp-mcp</span></span></code></pre></div><p>The server writes a line to stderr telling you which state it is in:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span>smtp-mcp: SMTP_ALLOW_SEND is not &quot;true&quot; — this server can compose and preview</span></span>
<span class="line"><span>messages but cannot send any. Set SMTP_ALLOW_SEND=true and SMTP_ALLOWED_RECIPIENTS</span></span>
<span class="line"><span>to enable sending.</span></span></code></pre></div><p>Ask your client to call <code>get_server_info</code>. It answers <code>can_send: false</code> and names the variable that would change that.</p><h2 id="turn-sending-on" tabindex="-1">Turn sending on <a class="header-anchor" href="#turn-sending-on" aria-label="Permalink to “Turn sending on”">​</a></h2><p>Two variables, and the second one is not optional:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">SMTP_ALLOW_SEND</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">true</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">SMTP_ALLOWED_RECIPIENTS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&#39;@example.net,partner@example.org&#39;</span></span></code></pre></div><p><code>SMTP_ALLOWED_RECIPIENTS</code> accepts:</p><table tabindex="0"><thead><tr><th>Entry</th><th>Matches</th></tr></thead><tbody><tr><td><code>@example.net</code></td><td>any address <strong>at</strong> that domain — not at <code>mail.example.net</code></td></tr><tr><td><code>person@example.net</code></td><td>exactly that address</td></tr><tr><td><code>*</code></td><td>anyone</td></tr></tbody></table><p>Setting <code>SMTP_ALLOW_SEND=true</code> without an allowlist is a startup error, not a silent &quot;anyone&quot;. That is deliberate: an unset allowlist reads as a line somebody forgot, and the failure it causes is a message already delivered. If you genuinely want no restriction, write <code>*</code> and own the choice.</p><h2 id="send-the-first-message" tabindex="-1">Send the first message <a class="header-anchor" href="#send-the-first-message" aria-label="Permalink to “Send the first message”">​</a></h2><p>Ask your client to send something, and watch what happens: the server does <strong>not</strong> send on the first call. It asks.</p><p>With a client that supports MCP elicitation — Claude Desktop and Claude Code do — a dialog appears with the recipients, the subject and any Bcc on their own lines. Nothing goes out until you tick it.</p><p>With a client that cannot show a dialog, the first call returns a confirmation token instead, and the tool has to be called a second time carrying it. The result says plainly that this only proves the call was made twice with the same arguments — it is not the same thing as a human saying yes, and it does not pretend to be.</p><p>Either way, a confirmation is bound to that exact message. Adding a recipient or changing the body invalidates it, and the server asks again.</p><h2 id="see-it-first" tabindex="-1">See it first <a class="header-anchor" href="#see-it-first" aria-label="Permalink to “See it first”">​</a></h2><p><code>preview_mail</code> builds exactly the message <code>send_mail</code> would build — same code path, same headers — and returns it without connecting to anything. Every check a send runs happens here too: the allowlist, the recipient limit, the attachment policy, the size limit. It is the fastest way to find out whether a message is acceptable before putting a question in front of a person.</p><h2 id="develop-against-a-sandbox" tabindex="-1">Develop against a sandbox <a class="header-anchor" href="#develop-against-a-sandbox" aria-label="Permalink to “Develop against a sandbox”">​</a></h2><p>If you are changing the server rather than using it, do not point it at a real mailbox. The repository ships a throwaway <a href="https://mailpit.axllent.org/" target="_blank" rel="noreferrer">Mailpit</a> instance that speaks real SMTP and delivers nowhere:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">docker</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> compose</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -f</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> test/integration/compose.yml</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> up</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -d</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> --wait</span></span>
<span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">npm</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> run</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> build</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> &amp;&amp; </span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">npm</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> run</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> test:integration</span></span></code></pre></div>`,25)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};